// "Buyruqni tanlash" — Buyruqlar varag'idan ishlatiladigan qatorni oladi.
// Status='Boshlash' bo'lgan OXIRGI qatorni, bo'lmasa eng oxirgi qatorni tanlaydi.
const rows = $input.all().map((i) => i.json);
if (!rows.length) {
  throw new Error("Buyruqlar varag'i bo'sh. Avval bir qator to'ldiring.");
}

let chosen = null;
for (let i = rows.length - 1; i >= 0; i--) {
  if (String(rows[i]['Status'] || '').trim() === 'Boshlash') {
    chosen = rows[i];
    break;
  }
}
if (!chosen) chosen = rows[rows.length - 1];

const vaqtMap = {
  'Bugun': { date_posted: 'last-day', cutoffDays: 1 },
  'Oxirgi hafta': { date_posted: 'last-week', cutoffDays: 7 },
  'Oxirgi oy': { date_posted: 'last-month', cutoffDays: 30 },
  'Oxirgi 3 oy': { date_posted: 'last-year', cutoffDays: 90 },
  'Oxirgi 6 oy': { date_posted: 'last-year', cutoffDays: 180 },
  "So'ngi yil": { date_posted: 'last-year', cutoffDays: 365 },
};

const vaqt = String(chosen['Vaqt'] || '').trim();
const v = vaqtMap[vaqt] || { date_posted: 'last-month', cutoffDays: 30 };
const miqdor = parseInt(chosen['Miqdor'], 10) || 10;

return [
  {
    json: {
      query: String(chosen['Buyruq'] || '').trim(),
      miqdor: miqdor,
      date_posted: v.date_posted,
      cutoffDays: v.cutoffDays,
      row_number: chosen.row_number,
    },
  },
];

// "Loop sozlash" — qidiruv holatini (searchState) global staticData'ga yozadi.
const cmd = $('Buyruqni tanlash').first().json;
const instaRows = $('Instagram dedup oqish').all().map((i) => i.json);

const existing = {};
for (const r of instaRows) {
  const id = String(r['Post IDsi'] || '').trim();
  if (id) existing[id] = true;
}

const cutoffTs = Math.floor(Date.now() / 1000) - cmd.cutoffDays * 24 * 60 * 60;

const st = {
  query: cmd.query,
  date_posted: cmd.date_posted,
  cutoffTs: cutoffTs,
  miqdor: cmd.miqdor,
  page: 1,
  startTime: Date.now(),
  collected: [],
  existing: existing,
  noMore: false,
  cmdRow: cmd.row_number,
};

$getWorkflowStaticData('global').searchState = st;

return [{ json: { started: true } }];

// "Tekshirish" — loop to'xtash shartlarini tekshiradi va done=true/false qaytaradi.
const st = $getWorkflowStaticData('global').searchState;

let done = false;
if (Date.now() - st.startTime > 5 * 60 * 1000) done = true; // 5 daqiqa timeout
if (st.collected.length >= st.miqdor) done = true; // yetarli yig'ildi
if (st.noMore) done = true; // boshqa natija yo'q
if (st.page > 20) done = true; // sahifa limiti

return [
  {
    json: {
      done: done,
      page: st.page,
      query: st.query,
      date_posted: st.date_posted,
      collected: st.collected.length,
    },
  },
];

// "Filtr va yig'ish" — ScrapeCreators javobidan reels'larni ajratib, filtrlab,
// searchState.collected ichiga to'playdi. So'ng page++ qiladi.
const st = $getWorkflowStaticData('global').searchState;
const resp = $input.first().json || {};

// Javobdan reels massivini turli ehtimoliy joylardan topish (himoyalangan).
let reels = [];
if (Array.isArray(resp.reels)) reels = resp.reels;
else if (Array.isArray(resp.results)) reels = resp.results;
else if (Array.isArray(resp.items)) reels = resp.items;
else if (Array.isArray(resp.data)) reels = resp.data;
else if (resp.data && Array.isArray(resp.data.items)) reels = resp.data.items;

function num(x) {
  const n = Number(x);
  return isNaN(n) ? 0 : n;
}
// Bir nechta ehtimoliy yo'ldan birinchi mavjud qiymatni oladi.
function pick(o, paths) {
  for (const p of paths) {
    let cur = o;
    let ok = true;
    for (const k of p.split('.')) {
      if (cur && typeof cur === 'object' && k in cur) cur = cur[k];
      else { ok = false; break; }
    }
    if (ok && cur !== undefined && cur !== null && cur !== '') return cur;
  }
  return undefined;
}

let added = 0;
for (const r of reels) {
  const m = r.media || r.node || r; // ba'zan asl obyekt media ichida bo'ladi
  const user = m.user || m.owner || r.user || {};

  const code = pick(m, ['code', 'shortcode']) || '';
  const pk = String(pick(m, ['pk', 'id', 'media_id']) || '').split('_')[0];
  const postId = String(code || pk || '').trim();
  if (!postId) continue;

  // dedup: jadvalda yoki shu yugurishda allaqachon bormi?
  if (st.existing[postId]) continue;

  const views = num(pick(m, ['play_count', 'ig_play_count', 'view_count', 'video_view_count', 'views']));
  if (!(views > 10000)) continue; // ko'rilish 10 000 dan ko'p bo'lsin

  const takenAt = num(pick(m, ['taken_at', 'taken_at_timestamp', 'device_timestamp']));
  if (takenAt && takenAt < st.cutoffTs) continue; // vaqt oralig'i

  const likes = num(pick(m, ['like_count', 'likes', 'edge_liked_by.count', 'edge_media_preview_like.count']));
  const comments = num(pick(m, ['comment_count', 'comments', 'edge_media_to_comment.count']));
  const caption = pick(m, ['caption.text', 'caption', 'edge_media_to_caption.edges.0.node.text']) || '';
  const account = pick(user, ['username']) || '';
  const accountId = String(pick(user, ['pk', 'id']) || '');
  const followers = num(pick(user, ['follower_count', 'edge_followed_by.count']));
  const havola = code
    ? `https://www.instagram.com/reel/${code}/`
    : (pick(m, ['permalink', 'url']) || r.url || '');

  st.existing[postId] = true;
  st.collected.push({
    postId, havola, views, likes, comments,
    takenAt, caption: String(caption), account, accountId, followers,
  });
  added++;
  if (st.collected.length >= st.miqdor) break;
}

if (reels.length === 0 || added === 0) {
  // bu sahifada yangi natija bo'lmasa — to'xtaymiz
  if (reels.length === 0) st.noMore = true;
}
st.page = st.page + 1;

return [{ json: { added: added, total: st.collected.length, page: st.page } }];

// "Yakuniy natija" — yig'ilganlarni miqdorgacha kesadi, Faollik hisoblaydi va
// Instagram varag'i ustunlariga mos obyektlar tayyorlaydi.
const st = $getWorkflowStaticData('global').searchState;
const list = (st.collected || []).slice(0, st.miqdor);

function faollik(views, likes, followers) {
  let reach;
  if (followers > 0) {
    const ratio = views / followers;
    reach = Math.min(100, (Math.log10(ratio + 1) / Math.log10(11)) * 100);
  } else {
    reach = views > 50000 ? 100 : (views / 50000) * 100;
  }
  let eng = 0;
  if (views > 0) {
    const er = likes / views;
    eng = Math.min(100, (er / 0.10) * 100);
  }
  const f = Math.round(0.6 * reach + 0.4 * eng);
  return Math.max(0, Math.min(100, f));
}

function ymd(ts) {
  if (!ts) return '';
  return new Date(ts * 1000).toISOString().slice(0, 10);
}
const today = new Date().toISOString().slice(0, 10);

const out = list.map((r) => ({
  'Akkaunt': r.account,
  'Opisaniya': r.caption,
  'Havola': r.havola,
  'Status': 'Yangi',
  'Skript tili': 'Uzbek',
  'Obunachilar': r.followers,
  'Faollik': faollik(r.views, r.likes, r.followers),
  "Ko'rilishlar": r.views,
  'Layklar': r.likes,
  'Kommentlar': r.comments,
  'Post sanasi': ymd(r.takenAt),
  'Kiritilish sanasi': today,
  'Post IDsi': r.postId,
  'Akkaunt IDsi': r.accountId,
}));

const cmdRow = st.cmdRow;
// holatni tozalaymiz (keyingi qidiruv toza boshlanishi uchun)
$getWorkflowStaticData('global').searchState = undefined;

return [{ json: { videos: out, count: out.length, cmdRow: cmdRow } }];

// "Videolarni yoyish" — videos massivini alohida item'larga yoyadi (append uchun).
const videos = $json.videos || [];
if (!videos.length) return [];
return videos.map((v) => ({ json: v }));
